  "2437": {
    "id": 2437,
    "furn_name": "Pedestal Huevaravilloso / Eggcellent Pedestal",
    "pivot": {
      "x": 0.5331,
      "y": 0.0482,
      "ui": 1.05
    },
    "rotations": {
      "B": 2456
    },
    "name_en": "Eggcellent Pedestal",
    "name_es": "Pedestal Huevaravilloso",
    "desc_en": "Here’s the thing: it’s a bunny paw. As a pedestal. It’s so random, it might just be genius. Plus, it’s a fun way to make your space 100% more... bunny-friendly? You’ll get a lot of questions. Mostly, \"why the paw?\"",
    "desc_es": "La cuestión es que es una pata de conejo. Como pedestal. Es tan inusual que podría ser genial. Además, es una forma divertida de hacer que tu espacio sea 100 % más... ¿amigable con los conejos? Recibirás muchas preguntas. Principalmente, \"¿por qué la pata?\""
  },
  "2438": {
    "id": 2438,
    "furn_name": "Repisa Huevaravillosa / Eggcellent Shelf",
    "width": 2,
    "length": 4,
    "pivot": {
      "x": 0.3816,
      "y": 0.0047,
      "ui": 1.43
    },
    "rotations": {
      "B": 2457
    },
    "name_en": "Eggcellent Shelf",
    "name_es": "Repisa Huevaravillosa",
    "desc_en": "Not sure who asked for it, but it’s here, and it’s great for showing off your precious little trinkets or your ever-growing collection of Egg Month-related items. Plus, every time you see it, you’ll remember how much you love bunnies. Like, a lot.",
    "desc_es": "No sé quién la pidió pero aquí está, es ideal para presumir de tus preciadas chucherías de tu creciente colección de artículos del Mes del Huevo. Además, cada vez que la veas, recordarás cuánto te encantan los conejitos. Muchísimo."
  },
  "2439": {
    "id": 2439,
    "item_name": "Banco Huevaravilloso / Eggcellent Bench",
    "furn_name": "Banco Huevaravilloso / Eggcellent Bench",
    "width": 3,
    "length": 2,
    "pivot": {
      "x": 0.6332,
      "y": 0.0831,
      "ui": 0.59
    },
    "rotations": {
      "B": 2458
    },
    "name_en": "Eggcellent Bench",
    "name_es": "Banco Huevaravilloso",
    "desc_en": "At some point, the designer just thought, \"You know what this bench needs? Bunnies. On both ends.\" When in doubt, add bunny ears, right? Who can blame them? It's basically a running theme at this point.",
    "desc_es": "En algún momento, el diseñador pensó: \"¿Sabes qué necesita este banco? Conejitos. En ambos extremos\". Ante la duda, añade orejas de conejo, ¿verdad? ¿Quién puede culparlos? Es prácticamente un tema recurrente en este momento."
  },
